module tb_TopModule;
  reg clk;
  reg L;
  reg [2:0] r;
  wire [2:0] q;

  // Instantiate 3 TopModules as in full_module
  // q[2]: q_in = q[1] ^ q[2], r_in = r[2]
  TopModule inst2 (
    .clk(clk),
    .L(L),
    .q_in(q[1] ^ q[2]),
    .r_in(r[2]),
    .Q(q[2])
  );

  // q[1]: q_in = q[0], r_in = r[1]
  TopModule inst1 (
    .clk(clk),
    .L(L),
    .q_in(q[0]),
    .r_in(r[1]),
    .Q(q[1])
  );

  // q[0]: q_in = q[2], r_in = r[0]
  TopModule inst0 (
    .clk(clk),
    .L(L),
    .q_in(q[2]),
    .r_in(r[0]),
    .Q(q[0])
  );

  initial begin
    clk = 0;
    forever #5 clk = ~clk;
  end

  initial begin
    L = 1;
    r = 3'b101;
    @(posedge clk);
    #1;
    if (q !== 3'b101) begin
      $display("FAIL: Load failed, expected 101, got %b", q);
      $finish;
    end

    // Test shifting / feedback mode
    L = 0;
    // Expected next: q[1]^q[2] = 0^1 = 1, q[0] = 1, q[2] = 1 -> {1, 1, 1} = 3'b111
    @(posedge clk);
    #1;
    if (q !== 3'b111) begin
      $display("FAIL: Cycle 1 failed, expected 111, got %b", q);
      $finish;
    end

    // Next cycle: q[1]^q[2] = 1^1 = 0, q[0] = 1, q[2] = 1 -> {0, 1, 1} = 3'b011
    @(posedge clk);
    #1;
    if (q !== 3'b011) begin
      $display("FAIL: Cycle 2 failed, expected 011, got %b", q);
      $finish;
    end

    $display("SELFTEST PASS");
    $finish;
  end
endmodule
